#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-only
"""Embed a dtc-built DTBO as a C array. This script does not run dtc."""
from __future__ import annotations

import pathlib
import sys

FDT_MAGIC = b"\xd0\x0d\xfe\xed"


def embed(blob: bytes) -> str:
    if len(blob) < 8 or blob[:4] != FDT_MAGIC:
        raise SystemExit("refusing to embed bytes that are not an FDT blob")
    lines = [
        "/* Generated by embed_dtbo.py from a dtc DTBO. Do not edit. */",
        "/* Pointer must be 8-byte aligned; a misaligned FDT is rejected. */",
        "static const _Alignas(8) unsigned char j713_dm_dtbo[] = {",
    ]
    for i in range(0, len(blob), 12):
        chunk = blob[i:i + 12]
        lines.append("\t" + ", ".join("0x%02x" % b for b in chunk) + ",")
    lines.append("};")
    lines.append("static const unsigned int j713_dm_dtbo_len = %u;" % len(blob))
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print("usage: embed_dtbo.py <input.dtbo> <output.inc>", file=sys.stderr)
        return 2
    blob = pathlib.Path(argv[1]).read_bytes()
    pathlib.Path(argv[2]).write_text(embed(blob))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
